export default {
  id: "organic",
  code: "TB125-2022",
  bar: "var(--c-organic)",
  tint: "var(--c-organic-bg)",
  nameTR: "Toprak Organik Maddesinin Yönetimi",
  nameEN: "Soil Organic Matter Management",
  topics: [
    { id: "fundamentals", name: "Temel Kavramlar" },
    { id: "decomposition", name: "Ayrışma Süreçleri" },
    { id: "practices", name: "Yönetim Uygulamaları" },
    { id: "structure-carbon", name: "Toprak Yapısı ve Karbon" }
  ],
  cards: [
    // --- fundamentals ---
    { id:"som", topic:"fundamentals", tr:"Toprak Organik Maddesi", en:"Soil organic matter (SOM)", def:"Ayrışmış bitki ve hayvan kalıntıları ile mikrobiyal biyokütleden oluşan toprağın organik kısmı.", defEn:"The organic fraction of soil built from decomposed plant and animal residues plus microbial biomass." },
    { id:"humus", topic:"fundamentals", tr:"Humus", en:"Humus", def:"Kalıntıların çoğu ayrıştıktan sonra geriye kalan, kararlı, koyu renkli ve dirençli organik madde.", defEn:"The stable, dark, resistant organic material that remains after most residues have decomposed." },
    { id:"labile-om", topic:"fundamentals", tr:"Labil Organik Madde", en:"Labile organic matter", def:"Toprak organik maddesinin kolay ayrışan, kısa ömürlü kısmı.", defEn:"The easily decomposable, short-lived fraction of soil organic matter." },
    { id:"humic-substances", topic:"fundamentals", tr:"Humik Maddeler", en:"Humic substances", def:"Humusun kimyasal olarak ayrıştırılabilen fraksiyonları — humik asit, fulvik asit ve humin; çözünürlük ve moleküler ağırlık bakımından birbirinden farklıdır.", defEn:"The chemically distinguishable fractions of humus — humic acid, fulvic acid, and humin — which differ in solubility and molecular weight." },
    { id:"particulate-organic-matter", topic:"fundamentals", tr:"Parçacıklı Organik Madde (POM)", en:"Particulate organic matter (POM)", def:"Kısmen ayrışmış bitki artıklarından oluşan, labil organik madde ile kararlı humus arasında bir ara aşamayı temsil eden organik madde fraksiyonu.", defEn:"An organic matter fraction made of partially decomposed plant residues, representing an intermediate stage between labile organic matter and stable humus." },
    { id:"soil-organic-carbon", topic:"fundamentals", tr:"Toprak Organik Karbonu (TOK)", en:"Soil organic carbon (SOC)", def:"Toprak organik maddesinin karbon içeriği; genellikle TOM/SOM tahmininde temel ölçülen bileşendir (TOM ≈ TOK × 1.72).", defEn:"The carbon content of soil organic matter; it's typically the component actually measured to estimate SOM (SOM ≈ SOC × 1.72)." },
    { id:"som-functions", topic:"fundamentals", tr:"Toprak Organik Maddesinin İşlevleri", en:"Functions of soil organic matter", def:"SOM'un toprağa kattığı üç temel işlev: fiziksel (strüktür, su tutma), kimyasal (besin döngüsü, KDK) ve biyolojik (mikrobiyal habitat) katkılar.", defEn:"The three broad roles SOM plays in soil: physical (structure, water holding), chemical (nutrient cycling, CEC), and biological (microbial habitat)." },
    { id:"soil-food-web", topic:"fundamentals", tr:"Toprak Besin Ağı", en:"Soil food web", def:"Bakteri, mantar, protozoa, nematod ve solucanlar gibi organizmaların, organik maddeyi ayrıştırıp besin döngüsünü sürdürdüğü, birbirine bağlı beslenme ilişkileri ağı.", defEn:"The interconnected feeding network of organisms — bacteria, fungi, protozoa, nematodes, earthworms — that decompose organic matter and drive nutrient cycling." },
    { id:"water-holding-om", topic:"fundamentals", tr:"Organik Maddenin Su Tutma Kapasitesine Etkisi", en:"SOM's effect on water-holding capacity", def:"Organik maddenin, kendi ağırlığının birkaç katı kadar su tutabilme özelliği sayesinde toprağın genel su tutma kapasitesini artırması.", defEn:"Organic matter's ability to hold several times its weight in water, which increases a soil's overall water-holding capacity." },
    { id:"om-cec-contribution", topic:"fundamentals", tr:"Organik Maddenin KDK'ye Katkısı", en:"SOM's contribution to CEC", def:"Humusun yüksek yüzey alanı ve negatif yük yoğunluğu nedeniyle, birim ağırlık başına kil minerallerinden çok daha fazla katyon değişim kapasitesi sağlaması.", defEn:"Because of its high surface area and negative charge density, humus provides far more cation exchange capacity per unit weight than clay minerals do." },

    // --- decomposition ---
    { id:"cn-ratio", topic:"decomposition", tr:"C:N Oranı", en:"C:N ratio", def:"Organik maddedeki karbonun azota oranı — ayrışma hızını belirleyen başlıca etken.", defEn:"The ratio of carbon to nitrogen in organic material — a major control on how fast it decomposes." },
    { id:"mineralization", topic:"decomposition", tr:"Mineralizasyon", en:"Mineralization", def:"Organik besin elementlerinin mikroorganizmalar tarafından inorganik, bitkiye yarayışlı formlara dönüştürülmesi.", defEn:"Microbial conversion of organic nutrients into inorganic, plant-available forms." },
    { id:"immobilization", topic:"decomposition", tr:"İmmobilizasyon", en:"Immobilization", def:"İnorganik besin elementlerinin mikroorganizmalar tarafından alınarak geçici olarak bitkiye yarayışsız hale getirilmesi.", defEn:"Microbial uptake of inorganic nutrients, temporarily making them unavailable to plants." },
    { id:"humification", topic:"decomposition", tr:"Humifikasyon", en:"Humification", def:"Taze organik kalıntıların kararlı humusa dönüştürülme süreci.", defEn:"The process by which fresh organic residues are transformed into stable humus." },
    { id:"decomposition-rate-factors", topic:"decomposition", tr:"Ayrışma Hızını Belirleyen Etkenler", en:"Factors controlling decomposition rate", def:"Sıcaklık, nem, havalanma ve C:N oranı — organik madde ayrışma hızını belirleyen başlıca çevresel ve kimyasal etkenler.", defEn:"Temperature, moisture, aeration, and C:N ratio — the main environmental and chemical factors controlling how fast organic matter decomposes." },
    { id:"priming-effect", topic:"decomposition", tr:"Tetikleme Etkisi (Priming Effect)", en:"Priming effect", def:"Taze, kolay ayrışan organik madde eklenmesinin, mikrobiyal aktiviteyi canlandırarak toprakta zaten var olan kararlı organik maddenin ayrışmasını da hızlandırması.", defEn:"The stimulation of decomposition of already-present, stable soil organic matter that occurs when fresh, easily decomposable organic matter is added, energizing microbial activity." },
    { id:"lignin-content", topic:"decomposition", tr:"Lignin İçeriği", en:"Lignin content", def:"Bitki dokusundaki, mikroorganizmalar tarafından parçalanması zor olan yapısal bir bileşik; yüksek lignin içeriği ayrışmayı yavaşlatır.", defEn:"A structural compound in plant tissue that's difficult for microorganisms to break down; high lignin content slows decomposition." },
    { id:"microbial-biomass", topic:"decomposition", tr:"Mikrobiyal Biyokütle", en:"Microbial biomass", def:"Topraktaki canlı mikroorganizmaların toplam kütlesi; hem ayrışmanın aktif motoru hem de geçici bir besin deposu olarak işlev görür.", defEn:"The total mass of living microorganisms in the soil; it serves as both the active engine of decomposition and a temporary nutrient reservoir." },
    { id:"co2-respiration", topic:"decomposition", tr:"CO₂ Solunumu (Toprak Solunumu)", en:"CO2 respiration (soil respiration)", def:"Mikroorganizmaların organik maddeyi ayrıştırırken saldığı CO₂ miktarının ölçülmesi; toprağın biyolojik aktivite düzeyinin bir göstergesidir.", defEn:"Measuring the amount of CO2 released as microorganisms decompose organic matter; an indicator of the soil's level of biological activity." },
    { id:"net-mineralization", topic:"decomposition", tr:"Net Mineralizasyon", en:"Net mineralization", def:"Mineralizasyon ile immobilizasyon arasındaki denge; net mineralizasyon pozitifse besin elementleri bitkiye yarayışlı hale gelir, negatifse mikroorganizmalarda kilitli kalır.", defEn:"The balance between mineralization and immobilization; when net mineralization is positive, nutrients become plant-available — when negative, they stay locked in microbes." },
    { id:"decomposer-succession", topic:"decomposition", tr:"Ayrıştırıcı Organizma Sırası", en:"Decomposer succession", def:"Ayrışma sürecinde, kolay parçalanan bileşikleri tüketen bakterilerin önce, zor parçalanan lignin gibi bileşikleri parçalayan mantarların ise daha sonra baskın hale gelmesi.", defEn:"During decomposition, bacteria that consume easily broken-down compounds dominate first, followed later by fungi that break down harder compounds like lignin." },

    // --- practices ---
    { id:"composting", topic:"practices", tr:"Kompostlama", en:"Composting", def:"Organik atığın, kontrollü ve genellikle aerobik biçimde ayrıştırılarak kararlı, humus benzeri bir ürüne dönüştürülmesi.", defEn:"Controlled, generally aerobic decomposition of organic waste into a stable, humus-like product." },
    { id:"green-manure", topic:"practices", tr:"Yeşil Gübre", en:"Green manure", def:"Toprağa karıştırılmak üzere özel olarak yetiştirilen, organik madde ve besin elementi katan bir örtü bitkisi.", defEn:"A cover crop grown specifically to be incorporated into the soil, adding organic matter and nutrients." },
    { id:"cover-crop", topic:"practices", tr:"Örtü Bitkisi", en:"Cover crop", def:"Hasat için değil, öncelikle toprağı korumak ve iyileştirmek için yetiştirilen bitki.", defEn:"A crop grown primarily to protect and improve soil rather than for harvest." },
    { id:"reduced-tillage", topic:"practices", tr:"Azaltılmış Toprak İşleme", en:"Reduced/no tillage", def:"Toprağın işlenme sıklığının veya yoğunluğunun azaltılması; organik maddenin parçalanmasını ve oksitlenmesini yavaşlatarak korunmasına yardımcı olur.", defEn:"Reducing the frequency or intensity of tillage; helps conserve organic matter by slowing its physical breakdown and oxidation." },
    { id:"crop-rotation", topic:"practices", tr:"Ürün Rotasyonu", en:"Crop rotation", def:"Aynı tarlada farklı ürünlerin sistematik biçimde art arda yetiştirilmesi; organik madde girdisini çeşitlendirir ve zararlı/hastalık döngülerini böler.", defEn:"Systematically growing different crops in sequence on the same field; diversifies organic matter inputs and breaks pest/disease cycles." },
    { id:"manure-application", topic:"practices", tr:"Hayvan Gübresi Uygulaması", en:"Manure application", def:"Yeşil gübreden farklı olarak, hayvan kaynaklı organik gübrenin toprağa uygulanması; hem besin hem organik madde girdisi sağlar.", defEn:"Unlike green manure, the application of animal-derived organic manure to soil, providing both nutrients and an organic matter input." },
    { id:"mulching", topic:"practices", tr:"Malçlama", en:"Mulching", def:"Toprak yüzeyinin organik (saman, talaş) veya inorganik bir materyalle kaplanması; nem kaybını azaltır, sıcaklığı dengeler ve zamanla organik madde katar.", defEn:"Covering the soil surface with an organic (straw, wood chips) or inorganic material; reduces moisture loss, moderates temperature, and adds organic matter over time." },
    { id:"biochar", topic:"practices", tr:"Biyokömür", en:"Biochar", def:"Organik biyokütlenin oksijensiz ortamda (pirolizle) ısıtılmasıyla üretilen, toprakta çok uzun süre kararlı kalan karbonca zengin bir toprak düzenleyicisi.", defEn:"A carbon-rich soil amendment produced by heating organic biomass in the absence of oxygen (pyrolysis); it remains stable in soil for a very long time." },
    { id:"residue-management", topic:"practices", tr:"Bitki Artığı Yönetimi", en:"Crop residue management", def:"Hasat sonrası tarlada kalan sap, anız gibi bitki artıklarının toprakta bırakılması, karıştırılması veya uzaklaştırılması kararı; organik madde dengesini doğrudan etkiler.", defEn:"The decision to leave, incorporate, or remove post-harvest plant residues like stalks and stubble — directly affects the organic matter balance." },
    { id:"vermicomposting", topic:"practices", tr:"Solucan Kompostu", en:"Vermicomposting", def:"Organik atığın, özellikle belirli solucan türleri kullanılarak ayrıştırılıp besin bakımından zengin bir toprak düzenleyicisine dönüştürülmesi.", defEn:"The decomposition of organic waste using specific earthworm species to produce a nutrient-rich soil amendment." },

    // --- structure-carbon ---
    { id:"aggregate-stability", topic:"structure-carbon", tr:"Toprak Agregat Stabilitesi", en:"Soil aggregate stability", def:"Toprak kümelerinin (agregatların) dağılmaya karşı direnci — organik madde içeriğiyle doğrudan artar.", defEn:"The resistance of soil clumps to breaking apart — improved directly by organic matter content." },
    { id:"carbon-sequestration", topic:"structure-carbon", tr:"Karbon Tutulumu", en:"Carbon sequestration", def:"Karbonun toprak organik maddesinde uzun süreli olarak depolanması; bu da atmosferdeki CO₂'yi dengeler.", defEn:"Long-term storage of carbon in soil organic matter, offsetting atmospheric CO₂." },
    { id:"glomalin", topic:"structure-carbon", tr:"Glomalin", en:"Glomalin", def:"Mikorizal mantarlar tarafından üretilen, toprak parçacıklarını bir arada tutarak agregat stabilitesine önemli katkı sağlayan yapışkan bir glikoprotein.", defEn:"A sticky glycoprotein produced by mycorrhizal fungi that binds soil particles together, contributing significantly to aggregate stability." },
    { id:"macro-micro-aggregates", topic:"structure-carbon", tr:"Makro ve Mikro Agregatlar", en:"Macroaggregates and microaggregates", def:"Makroagregatlar (>250 μm) daha büyük, kök ve hif ağlarınca bir arada tutulan kümelerdir; bunların içinde daha küçük, kimyasal bağlarla oluşan mikroagregatlar bulunur.", defEn:"Macroaggregates (>250 μm) are larger clumps held together by roots and fungal hyphae; within them are smaller microaggregates formed by chemical bonds." },
    { id:"carbon-saturation", topic:"structure-carbon", tr:"Karbon Doygunluğu", en:"Soil organic carbon saturation", def:"Bir toprağın, kil ve silt parçacıklarıyla fiziksel olarak koruyabileceği organik karbon miktarının bir üst sınırı olduğu ve bu sınıra yaklaştıkça ek karbon depolamanın zorlaştığı kavramı.", defEn:"The concept that a soil has an upper limit to how much organic carbon its clay and silt particles can physically protect, making additional storage harder as that limit is approached." },
    { id:"om-bulk-density-link", topic:"structure-carbon", tr:"Organik Maddenin Hacim Ağırlığına Etkisi", en:"SOM's effect on bulk density", def:"Organik maddenin toprağa eklenmesinin, gözenekliliği artırarak hacim ağırlığını düşürmesi ve böylece kök nüfuzunu kolaylaştırması.", defEn:"Adding organic matter to soil increases porosity and lowers bulk density, making it easier for roots to penetrate." },
    { id:"om-infiltration", topic:"structure-carbon", tr:"Organik Maddenin Su Sızma Hızına Etkisi", en:"SOM's effect on infiltration", def:"Organik maddenin, stabil agregatlar oluşturarak su geçirgen gözenekler yaratması ve böylece yüzey akışını azaltıp su sızmasını artırması.", defEn:"Organic matter creates stable aggregates with water-permeable pores, reducing surface runoff and increasing water infiltration." },
    { id:"om-erosion-resistance", topic:"structure-carbon", tr:"Organik Maddenin Erozyon Direncine Katkısı", en:"SOM's contribution to erosion resistance", def:"Kararlı agregatların, tekil toprak parçacıklarının rüzgar veya suyla kolayca taşınmasını zorlaştırarak erozyona karşı direnç sağlaması.", defEn:"Stable aggregates make it harder for individual soil particles to be carried away by wind or water, providing resistance to erosion." },
    { id:"active-vs-stable-carbon", topic:"structure-carbon", tr:"Aktif ve Kararlı Karbon Havuzları", en:"Active vs. stable carbon pools", def:"Toprak organik karbonunun, hızla döngüye giren 'aktif' bir fraksiyon ile onlarca-yüzlerce yıl kalabilen 'kararlı' (pasif) bir fraksiyona ayrılması.", defEn:"Soil organic carbon is divided into a rapidly cycling 'active' fraction and a 'stable' (passive) fraction that can persist for decades to centuries." },
    { id:"soil-carbon-pools-turnover", topic:"structure-carbon", tr:"Karbon Havuzlarının Döngü Süresi", en:"Carbon pool turnover time", def:"Farklı organik madde fraksiyonlarının topraktan tamamen kaybolmadan önce toprakta kalma süresi; labil fraksiyon aylar, kararlı fraksiyon ise yüzyıllar sürebilir.", defEn:"The length of time different organic matter fractions remain in soil before being lost; the labile fraction may last months, the stable fraction centuries." },
    { id:"climate-carbon-sequestration", topic:"structure-carbon", tr:"İklim Değişikliği ve Karbon Tutulumu", en:"Climate change and carbon sequestration", def:"Toprakta karbon tutulumunun, atmosferdeki CO₂'yi azaltarak iklim değişikliğini hafifletme potansiyeli olan bir doğal çözüm olarak değerlendirilmesi.", defEn:"Soil carbon sequestration viewed as a natural climate solution with the potential to mitigate climate change by drawing down atmospheric CO2." }
  ],
  quiz: [
    // --- fundamentals (15) ---
    { id:"q-humus-vs-fresh", topic:"fundamentals", q:"Humusu taze organik kalıntıdan ayıran nedir?", qEn:"What distinguishes humus from fresh organic residue?", opts:["Humus daha hızlı ayrışır","Humus, kapsamlı ayrışma sonrası oluşan, kararlı ve koyu renkli, daha fazla parçalanmaya dirençli bir materyaldir","Humus karbon içermez","Taze kalıntı daha kararlıdır"], a:1, ex:"Humus, humifikasyonun son ürünüdür — kimyasal olarak kararlı hale gelmiştir ve geldiği taze materyalden çok daha yavaş ayrışır.", exEn:"Humus is the end product of humification — chemically stabilized and far slower to break down than the fresh material it came from." },
    { id:"q-humic-substances-fractions", topic:"fundamentals", q:"Humik maddeler kavramı hangi üç fraksiyonu kapsar?", qEn:"What three fractions does the concept of humic substances cover?", opts:["Kum, mil, kil","Humik asit, fulvik asit, humin","Azot, fosfor, potasyum","Bakteri, mantar, arke"], a:1, ex:"Bu üç fraksiyon, çözünürlük ve moleküler ağırlık bakımından farklılık gösteren, humusun kimyasal olarak ayrıştırılabilen bileşenleridir.", exEn:"These three fractions, differing in solubility and molecular weight, are the chemically distinguishable components of humus." },
    { id:"q-pom-stage", topic:"fundamentals", q:"Parçacıklı organik madde (POM), organik madde ayrışma sürecinde hangi aşamayı temsil eder?", qEn:"What stage does particulate organic matter (POM) represent in the organic matter decomposition process?", opts:["En kararlı, en yaşlı fraksiyonu","Labil organik madde ile kararlı humus arasında bir ara aşamayı","Yalnızca taze, hiç ayrışmamış artıkları","Mineral toprak parçacıklarını"], a:1, ex:"POM, kısmen ayrışmış bitki artıklarından oluşur ve henüz tam anlamıyla kararlı humusa dönüşmemiştir.", exEn:"POM consists of partially decomposed plant residues that haven't yet fully transformed into stable humus." },
    { id:"q-soc-vs-som", topic:"fundamentals", q:"Toprak organik karbonu (TOK) ile toprak organik maddesi (TOM) arasındaki ilişki nedir?", qEn:"What is the relationship between soil organic carbon (SOC) and soil organic matter (SOM)?", opts:["Aynı şeydir, birebir eşittir","TOK, TOM'un ölçülen karbon bileşenidir; TOM genellikle TOK'nin yaklaşık 1.72 katı olarak tahmin edilir","TOM her zaman TOK'den küçüktür","TOK yalnızca kum içeriğini ifade eder"], a:1, ex:"Laboratuvarlar genellikle doğrudan karbonu (TOK) ölçer ve TOM'u bir dönüşüm faktörüyle (yaklaşık ×1.72) tahmin eder.", exEn:"Labs typically measure carbon (SOC) directly and estimate SOM using a conversion factor (roughly ×1.72)." },
    { id:"q-som-three-functions", topic:"fundamentals", q:"Toprak organik maddesinin toprağa sağladığı üç temel işlev kategorisi nelerdir?", qEn:"What are the three main function categories soil organic matter provides to soil?", opts:["Yalnızca renk, koku, tat","Fiziksel, kimyasal ve biyolojik katkılar","Yalnızca ekonomik katkılar","Yalnızca estetik katkılar"], a:1, ex:"SOM aynı anda strüktürü iyileştirir (fiziksel), besin/KDK sağlar (kimyasal) ve mikrobiyal yaşamı destekler (biyolojik) — bu çok yönlülük onu bu kadar değerli kılar.", exEn:"SOM simultaneously improves structure (physical), supplies nutrients/CEC (chemical), and supports microbial life (biological) — this versatility is what makes it so valuable." },
    { id:"q-soil-food-web-def", topic:"fundamentals", q:"Toprak besin ağı kavramı neyi ifade eder?", qEn:"What does the concept of the soil food web refer to?", opts:["Yalnızca bitki köklerini","Bakteri, mantar, protozoa, nematod ve solucanlar gibi organizmaların birbirine bağlı beslenme ilişkileri ağını","Yalnızca toprak testinde kullanılan cihazları","Yalnızca tarımsal ürünleri"], a:1, ex:"Bu organizmalar birbirini besleyerek (örn. protozoa bakteriyle beslenir) organik maddenin ayrışmasını ve besin döngüsünü birlikte yürütür.", exEn:"These organisms feed on each other (e.g. protozoa consume bacteria), jointly driving organic matter decomposition and nutrient cycling." },
    { id:"q-om-water-holding", topic:"fundamentals", q:"Organik madde, toprağın su tutma kapasitesini nasıl artırır?", qEn:"How does organic matter increase a soil's water-holding capacity?", opts:["Su tutma kapasitesini azaltır, artırmaz","Kendi ağırlığının birkaç katı kadar su tutabilme özelliği sayesinde","Yalnızca toprağın rengini koyulaştırarak","Su tutma kapasitesiyle hiçbir ilgisi yoktur"], a:1, ex:"Organik madde, sünger benzeri yapısı sayesinde önemli miktarda suyu tutabilir; bu da kuraklık dönemlerinde bitkiler için tampon görevi görür.", exEn:"Thanks to its sponge-like structure, organic matter can hold significant amounts of water, acting as a buffer for plants during dry spells." },
    { id:"q-humus-cec-reason", topic:"fundamentals", q:"Humus, birim ağırlık başına neden kil minerallerinden daha fazla KDK sağlayabilir?", qEn:"Why can humus provide more CEC per unit weight than clay minerals?", opts:["Humus hiçbir zaman KDK sağlamaz","Humusun yüzey alanı ve negatif yük yoğunluğu kil minerallerinden daha yüksektir","Kil mineralleri hiç yük taşımaz","KDK yalnızca mineral parçacıklardan kaynaklanır"], a:1, ex:"Humusun kimyasal yapısı, birim ağırlık başına kile göre çok daha fazla negatif yüklü değişim bölgesi sunar.", exEn:"Humus's chemical structure offers far more negatively charged exchange sites per unit weight than clay." },
    { id:"q-som-vs-humus-relationship", topic:"fundamentals", q:"Toprak organik maddesi (SOM) ile humus arasındaki ilişki nedir?", qEn:"What is the relationship between soil organic matter (SOM) and humus?", opts:["Aynı şeydir, eş anlamlıdır","SOM, taze artıklardan kararlı humusa kadar tüm organik bileşenleri kapsayan geniş bir kategoridir; humus bunun en kararlı alt fraksiyonudur","Humus, SOM'dan daha büyük bir kategoridir","SOM yalnızca canlı organizmaları ifade eder"], a:1, ex:"SOM şemsiye bir terimdir — canlı organizmalar, taze kalıntılar, POM ve humus dahil her şeyi kapsar; humus ise bunların en ayrışmış, en kararlı ürünüdür.", exEn:"SOM is an umbrella term covering everything from living organisms to fresh residues, POM, and humus; humus is the most decomposed, most stable product among them." },
    { id:"q-labile-vs-pom", topic:"fundamentals", q:"Labil organik madde ile parçacıklı organik madde (POM) arasındaki fark nedir?", qEn:"What is the difference between labile organic matter and particulate organic matter (POM)?", opts:["Aynı fraksiyondur","Labil organik madde en kolay ayrışan, en kısa ömürlü fraksiyondur; POM ise kısmen ayrışmış, biraz daha kararlı bir ara aşamadır","POM her zaman labil organik maddeden daha hızlı ayrışır","Labil organik madde yalnızca minerallerden oluşur"], a:1, ex:"İkisi de görece genç fraksiyonlardır, ancak POM labil fraksiyona göre biraz daha fazla ayrışmış ve biraz daha yavaş döngüye sahiptir.", exEn:"Both are relatively young fractions, but POM is somewhat more decomposed and cycles more slowly than the labile fraction." },
    { id:"q-protozoa-bacteria-mineralization", topic:"fundamentals", q:"Toprak besin ağında protozoa gibi organizmaların bakterileri tüketmesi, besin döngüsüne nasıl katkıda bulunur?", qEn:"How does protozoa consuming bacteria in the soil food web contribute to nutrient cycling?", opts:["Hiçbir katkısı yoktur, yalnızca bakteri sayısını azaltır","Bakteri bünyesindeki azotun bir kısmını mineralize ederek bitkiye yarayışlı hale getirir","Yalnızca karbonu tüketir, azotu etkilemez","Toprak besin ağı yalnızca bitkiler arasında işler"], a:1, ex:"Protozoa, bakterilerden daha fazla azota ihtiyaç duyduğundan, tükettiği bakterideki fazla azotu amonyum olarak dışarı atar — bu doğrudan bir mineralizasyon kaynağıdır.", exEn:"Since protozoa need proportionally less nitrogen than bacteria, they excrete the surplus nitrogen from consumed bacteria as ammonium — a direct source of mineralization." },
    { id:"q-som-multifunction", topic:"fundamentals", q:"Bir toprakta organik madde artışı, hem su tutma kapasitesini hem KDK'yi hem de agregat stabilitesini aynı anda neden iyileştirebilir?", qEn:"Why can an increase in organic matter improve water-holding capacity, CEC, and aggregate stability all at once?", opts:["Tesadüftür, birbirleriyle ilgileri yoktur","Organik maddenin fiziksel (su tutma, agregatlaşma) ve kimyasal (yük yoğunluğu) özellikleri aynı anda birden fazla toprak fonksiyonuna katkıda bulunur","Yalnızca birini iyileştirebilir, diğerleri etkilenmez","Bu iyileşmeler yalnızca kumlu topraklarda görülür"], a:1, ex:"Organik maddenin çok yönlü doğası — hem fiziksel hem kimyasal özellikleri — onu SOM yönetimini bu kadar değerli kılan tek bir 'her derde deva' girdi haline getirir.", exEn:"Organic matter's multifaceted nature — both physical and chemical properties — makes it a single input that benefits multiple soil functions at once, which is why managing SOM is so valuable." },
    { id:"q-soc-measurement-preference", topic:"fundamentals", q:"Toprak organik karbonunun doğrudan ölçülmesi neden tercih edilir?", qEn:"Why is directly measuring soil organic carbon preferred?", opts:["TOM'u doğrudan ölçmek imkansız olduğu ve karbon analitik olarak daha güvenilir ölçülebildiği için","TOK'nin TOM ile hiçbir ilişkisi olmadığı için","Yalnızca ucuz olduğu için, başka nedeni yok","TOK yalnızca tahmini bir değerdir, hiç ölçülmez"], a:0, ex:"Karbon içeriği, yanma veya oksitleme yöntemleriyle analitik olarak doğru bir şekilde ölçülebilir; TOM ise bu ölçümden bir dönüşüm faktörüyle tahmin edilir.", exEn:"Carbon content can be measured analytically and accurately through combustion or oxidation methods; SOM is then estimated from that measurement using a conversion factor." },
    { id:"q-fulvic-vs-humic-acid", topic:"fundamentals", q:"Fulvik asit ile humik asit arasındaki temel ayrım genellikle neye dayanır?", qEn:"What is the key distinction between fulvic acid and humic acid usually based on?", opts:["Rengine, ikisi de aynı renktedir","Çözünürlüklerine — fulvik asit hem asidik hem bazik koşullarda çözünür kalırken, humik asit asidik koşullarda çökelir","Topraktaki miktarlarına, her zaman eşittirler","İkisi de aynı moleküler ağırlığa sahiptir"], a:1, ex:"Bu fraksiyonlar geleneksel olarak çözünürlük davranışlarına göre ayrılır; fulvik asit daha küçük moleküllü ve daha geniş pH aralığında çözünürdür.", exEn:"These fractions are traditionally separated by solubility behavior; fulvic acid has a smaller molecular size and stays soluble across a wider pH range." },
    { id:"q-food-web-disease-suppression", topic:"fundamentals", q:"Çeşitliliği yüksek bir toprak besin ağının, bitki hastalığı baskılanmasına nasıl katkısı olabilir?", qEn:"How can a highly diverse soil food web contribute to plant disease suppression?", opts:["Hiçbir katkısı yoktur","Faydalı mikroorganizmalar, patojenlerle besin ve alan için rekabet ederek veya onları doğrudan baskılayarak koruyucu bir rol oynayabilir","Toprak besin ağı yalnızca besin döngüsüyle ilgilidir, hastalıkla ilgisi yoktur","Besin ağı çeşitliliği hastalık riskini her zaman artırır"], a:1, ex:"Zengin ve çeşitli bir mikrobiyal topluluk, patojenlerin yerleşip çoğalabileceği boş nişleri doldurarak doğal bir baskılayıcı etki yaratabilir.", exEn:"A rich, diverse microbial community can create a natural suppressive effect by filling the empty niches pathogens would otherwise colonize." },

    // --- decomposition (15) ---
    { id:"q-high-cn-effect", topic:"decomposition", q:"Toprağa yüksek C:N oranlı bir materyal (örn. saman, ~80:1) eklendiğinde genel etki nedir?", qEn:"What is the general effect of a high C:N ratio material (e.g. straw, ~80:1) when added to soil?", opts:["Hızlı ayrışma ve fazla yarayışlı azot","Yavaş ayrışma ve mikroorganizmalar tarafından geçici azot immobilizasyonu","Azot üzerinde hiçbir etki yok","Anında humus oluşumu"], a:1, ex:"Karbonca zengin, azotça fakir kalıntıyı ayrıştıran mikroorganizmalar, kendi bünyelerini oluşturmak için topraktan azot çeker ve bunu geçici olarak bağlar.", exEn:"Microbes breaking down carbon-rich, nitrogen-poor residue pull nitrogen from the soil to build their own bodies, temporarily tying it up." },
    { id:"q-mineralization-def", topic:"decomposition", q:"Organik madde döngüsünde 'mineralizasyon' nedir?", qEn:"What is 'mineralization' in the organic matter cycle?", opts:["Kayadan toprak minerali oluşumu","Organik besin elementlerinin mikroorganizmalarca inorganik, bitkiye yarayışlı formlara dönüştürülmesi","Sentetik gübre eklenmesi","Erozyonla organik madde kaybı"], a:1, ex:"Mineralizasyon, N, P ve S gibi besin elementlerini organik maddeden köklerin doğrudan alabileceği formlara serbest bırakır.", exEn:"Mineralization releases nutrients like N, P, and S from organic matter into forms roots can directly absorb." },
    { id:"q-immobilization-def", topic:"decomposition", q:"Besin elementlerinin 'immobilizasyonu' nedir?", qEn:"What is 'immobilization' of nutrients?", opts:["Sistemden kalıcı besin kaybı","İnorganik besin elementlerinin mikroorganizmalarca geçici olarak alınıp kısa vadede bitkiye yarayışsız hale getirilmesi","Besin elementlerinin daha derin katmanlara hareketi","Besin elementlerinin gaza dönüşmesi"], a:1, ex:"İmmobilize olan besin elementleri kaybolmaz — mikroorganizmalar ölüp bunları tekrar serbest bırakana (mineralizasyon) kadar mikrobiyal biyokütlede kilitli kalır.", exEn:"Immobilized nutrients aren't lost — they're locked in microbial biomass until the microbes die and release them again (mineralization)." },
    { id:"q-decomposition-rate-factors", topic:"decomposition", q:"Organik madde ayrışma hızını belirleyen başlıca etkenler nelerdir?", qEn:"What are the main factors controlling the rate of organic matter decomposition?", opts:["Yalnızca toprağın rengi","Sıcaklık, nem, havalanma ve C:N oranı","Yalnızca toprağın tuzluluğu","Yalnızca ürün türü"], a:1, ex:"Bu dört etken, mikrobiyal aktivitenin hızını ve dolayısıyla organik maddenin ne kadar hızlı ayrıştığını birlikte belirler.", exEn:"These four factors together determine the pace of microbial activity, and therefore how fast organic matter decomposes." },
    { id:"q-priming-effect-def", topic:"decomposition", q:"Tetikleme etkisi (priming effect) neyi ifade eder?", qEn:"What does the priming effect refer to?", opts:["Organik maddenin hiç ayrışmaması","Taze organik madde eklenmesinin, mikrobiyal aktiviteyi canlandırarak zaten var olan kararlı organik maddenin ayrışmasını da hızlandırması","Yalnızca sentetik gübrelerin etkisini ifade eder","Toprak pH'ının ani değişimini ifade eder"], a:1, ex:"Taze, kolay ayrışan bir girdi, mikrobiyal popülasyonu ve enzim üretimini artırarak dolaylı olarak eski, kararlı organik maddenin de bir kısmının ayrışmasını hızlandırabilir.", exEn:"A fresh, easily decomposed input can boost microbial populations and enzyme production, indirectly speeding up decomposition of some already-stable organic matter too." },
    { id:"q-lignin-slow-decomposition", topic:"decomposition", q:"Yüksek lignin içeriğine sahip bitki artıkları (örn. odunsu materyal) neden yavaş ayrışır?", qEn:"Why do plant residues high in lignin (e.g. woody material) decompose slowly?", opts:["Lignin mikroorganizmalar için kolay bir besin kaynağıdır","Lignin, çoğu mikroorganizmanın etkili biçimde parçalayamadığı karmaşık, dirençli bir yapısal bileşiktir","Lignin toprakta hiç bulunmaz","Yüksek lignin içeriği ayrışmayı hızlandırır"], a:1, ex:"Lignini parçalayabilen sınırlı sayıda organizma (başta belirli mantarlar) vardır; bu yüzden yüksek lignin içeriği ayrışmayı belirgin biçimde yavaşlatır.", exEn:"Only a limited set of organisms (chiefly certain fungi) can break down lignin, which is why a high lignin content markedly slows decomposition." },
    { id:"q-microbial-biomass-dual-role", topic:"decomposition", q:"Mikrobiyal biyokütle, organik madde döngüsünde hangi ikili rolü oynar?", qEn:"What dual role does microbial biomass play in the organic matter cycle?", opts:["Yalnızca pasif bir gözlemcidir","Hem ayrışmanın aktif motorudur hem de geçici bir besin deposu olarak işlev görür","Yalnızca karbon tüketir, hiçbir şey üretmez","Toprak besin döngüsüyle ilgisi yoktur"], a:1, ex:"Mikroorganizmalar organik maddeyi aktif olarak parçalarken, kendi bünyelerinde de besin biriktirir; öldüklerinde bu besinler tekrar döngüye girer.", exEn:"As microorganisms actively break down organic matter, they also accumulate nutrients in their own bodies; when they die, those nutrients re-enter the cycle." },
    { id:"q-respiration-activity-indicator", topic:"decomposition", q:"Toprak solunumu (CO₂ salınımı) ölçümü neyin bir göstergesi olarak kullanılır?", qEn:"What is measuring soil respiration (CO2 release) used as an indicator of?", opts:["Toprağın renginin","Toprağın biyolojik aktivite düzeyinin","Yalnızca toprağın nem içeriğinin","Toprağın tuzluluğunun"], a:1, ex:"Mikroorganizmalar organik maddeyi ayrıştırırken CO₂ salar; bu salınımın ölçülmesi, toprak biyolojik aktivitesinin dolaylı ama etkili bir göstergesidir.", exEn:"Microorganisms release CO2 as they decompose organic matter; measuring that release is an indirect but effective indicator of soil biological activity." },
    { id:"q-net-mineralization-positive", topic:"decomposition", q:"Net mineralizasyonun pozitif olması ne anlama gelir?", qEn:"What does it mean when net mineralization is positive?", opts:["İmmobilizasyon mineralizasyondan daha fazladır, besinler kilitlenir","Mineralizasyon immobilizasyondan daha fazladır, besin elementleri net olarak bitkiye yarayışlı hale gelir","Hiçbir besin döngüsü gerçekleşmemektedir","Toprak tamamen sterildir"], a:1, ex:"Net mineralizasyon, mineralizasyon ile immobilizasyon arasındaki dengedir; pozitifse mikroorganizmalardan bitkiye net bir besin akışı vardır.", exEn:"Net mineralization is the balance between mineralization and immobilization; when positive, there is a net flow of nutrients from microbes to the plant." },
    { id:"q-decomposer-early-succession", topic:"decomposition", q:"Ayrışma sürecinin başlangıcında hangi organizma grubu genellikle baskındır?", qEn:"Which group of organisms typically dominates at the start of decomposition?", opts:["Lignin parçalayan mantarlar","Kolay parçalanan şekerleri ve basit bileşikleri tüketen bakteriler","Yalnızca solucanlar","Yalnızca protozoa"], a:1, ex:"Ayrışmanın erken aşamasında bakteriler, kolay erişilebilir kolay bileşikleri hızla tüketir; zor parçalanan lignin gibi bileşikler için daha sonra mantarlar baskın hale gelir.", exEn:"Bacteria dominate the early stage, rapidly consuming easily accessible simple compounds; fungi become dominant later, for harder compounds like lignin." },
    { id:"q-low-cn-fast-decomposition", topic:"decomposition", q:"Düşük C:N oranına sahip bir materyal (örn. taze baklagil artığı) neden hızlı ayrışır?", qEn:"Why does a material with a low C:N ratio (e.g. fresh legume residue) decompose quickly?", opts:["Düşük C:N, mikroorganizmaların azot ihtiyacını kolayca karşılamasını sağlar, bu da hızlı büyüme ve ayrışmaya yol açar","Düşük C:N ayrışmayı yavaşlatır","C:N oranının ayrışma hızıyla hiçbir ilgisi yoktur","Düşük C:N materyal hiç ayrışmaz"], a:0, ex:"Mikroorganizmaların büyümesi için hem karbon hem azot gerekir; düşük C:N oranlı materyal azot açısından zengin olduğundan mikrobiyal büyümeyi ve dolayısıyla ayrışmayı hızlandırır.", exEn:"Microbial growth needs both carbon and nitrogen; a low-C:N material is nitrogen-rich, which fuels microbial growth and therefore faster decomposition." },
    { id:"q-priming-management-implication", topic:"decomposition", q:"Tetikleme etkisi, çiftçilerin taze organik madde (örn. yeşil gübre) eklemesiyle ilgili neyi akılda tutmasını gerektirir?", qEn:"What should the priming effect remind farmers to keep in mind when adding fresh organic matter (e.g. green manure)?", opts:["Hiçbir şeyi, taze madde eklemenin yan etkisi yoktur","Taze madde eklemenin, kısa vadede toprakta zaten depolanmış kararlı karbonun bir kısmının da kaybına yol açabileceğini","Taze madde eklemenin toprak karbonunu asla etkilemediğini","Tetikleme etkisinin yalnızca laboratuvar koşullarında gerçekleştiğini"], a:1, ex:"Tetikleme etkisi, kısa vadeli bir karbon kaybına yol açabilir; ancak uzun vadede düzenli organik madde girdisi genellikle toplam SOM'u artırır.", exEn:"The priming effect can cause a short-term carbon loss, but consistent long-term organic matter input generally still increases total SOM." },
    { id:"q-respiration-management-comparison", topic:"decomposition", q:"Toprak solunum testleri, bir arazi yöneticisine pratik olarak neyi gösterebilir?", qEn:"What can soil respiration tests practically show a land manager?", opts:["Yalnızca toprağın fiyatını","Farklı yönetim uygulamalarının (işleme, örtü bitkisi vb.) mikrobiyal aktivite üzerindeki etkisini karşılaştırmalı olarak","Yalnızca hava durumu tahminini","Toprağın jeolojik yaşını"], a:1, ex:"Solunum ölçümleri, örneğin azaltılmış toprak işlemenin geleneksel işlemeye göre mikrobiyal aktiviteyi nasıl etkilediğini karşılaştırmak için kullanılabilir.", exEn:"Respiration measurements can, for example, compare how reduced tillage affects microbial activity relative to conventional tillage." },
    { id:"q-succession-residue-quality", topic:"decomposition", q:"Kolay ayrışan bir bitki artığı ile odunsu, lignin bakımından zengin bir artık aynı tarlaya eklenirse, ayrıştırıcı topluluk zamanla nasıl değişir?", qEn:"If an easily decomposed residue and a woody, lignin-rich residue are added to the same field, how does the decomposer community change over time?", opts:["Değişmez, aynı organizmalar her ikisini de aynı hızda parçalar","Önce bakteriler kolay bileşikleri tüketir; lignince zengin materyal kaldıkça mantarlar zamanla daha baskın hale gelir","Yalnızca mantarlar her iki materyali de parçalayabilir","Yalnızca bakteriler her iki materyali de parçalayabilir"], a:1, ex:"Materyalin bileşimi, hangi ayrıştırıcı grubun baskın olacağını zamanla şekillendirir — kolay bileşikler tükendikçe topluluk mantar ağırlıklı hale kayar.", exEn:"Material composition shapes which decomposer group dominates over time — as easy compounds are used up, the community shifts toward fungi." },
    { id:"q-cn-threshold-immobilization", topic:"decomposition", q:"Bir organik materyalin C:N oranı yaklaşık 20-25:1'in üzerine çıktığında mineralizasyon-immobilizasyon dengesi genellikle hangi yöne kayar?", qEn:"When an organic material's C:N ratio rises above roughly 20-25:1, which way does the mineralization-immobilization balance typically shift?", opts:["Net mineralizasyona, besin fazlası oluşur","Net immobilizasyona, mikroorganizmalar toprak azotunu tüketmeye başlar","Dengeyi hiç etkilemez","Her zaman tam dengede kalır"], a:1, ex:"C:N oranı belirli bir eşiği (yaklaşık 20-25:1) aştığında, mikroorganizmaların azot ihtiyacı materyalin kendi azot içeriğini aşar ve toprak azotunu tüketmeye (immobilize etmeye) başlarlar.", exEn:"Once the C:N ratio crosses a certain threshold (around 20-25:1), microbial nitrogen demand exceeds the material's own nitrogen content, and microbes start drawing down (immobilizing) soil nitrogen." },

    // --- practices (15) ---
    { id:"q-cover-crops-why", topic:"practices", q:"Örtü bitkileri veya yeşil gübreler organik madde yönetiminde neden kullanılır?", qEn:"Why are cover crops or green manures used in organic matter management?", opts:["Toprağı sıkıştırmak için","Organik madde eklemek, erozyona karşı korumak ve genellikle azot bağlamak için","Mikrobiyal aktiviteyi azaltmak için","Toprak tuzluluğunu artırmak için"], a:1, ex:"Özellikle baklagil örtü bitkileri hem biyokütle hem de bağlanmış azot katarken, kökleri ana ürünler arasında toprağı yerinde tutar.", exEn:"Legume cover crops in particular add both biomass and fixed nitrogen while their roots hold soil in place between main crops." },
    { id:"q-composting-def", topic:"practices", q:"Organik madde yönetimi açısından kompostlama nedir?", qEn:"What is composting, in organic matter management terms?", opts:["Kontrolsüz anaerobik çürüme","Organik atığı kararlı, humus benzeri bir ürüne dönüştüren, kontrollü ve genellikle aerobik bir süreç","Laboratuvarda organik maddenin kimyasal sentezi","Bir toprak örnekleme yöntemi"], a:1, ex:"Kompostlama; nem, havalanma ve C:N oranını bilinçli şekilde yöneterek kullanılabilir bir toprak düzenleyicisine dönüşümü hızlandırır.", exEn:"Composting deliberately manages moisture, aeration, and C:N ratio to speed stabilization into a usable soil amendment." },
    { id:"q-reduced-tillage-conservation", topic:"practices", q:"Azaltılmış toprak işleme, organik madde korunumuna nasıl katkıda bulunur?", qEn:"How does reduced tillage contribute to organic matter conservation?", opts:["Organik maddeyi hızla oksitleyerek yok eder","Toprağın fiziksel olarak parçalanmasını azaltarak organik maddenin oksitlenme ve kaybolma hızını yavaşlatır","Organik madde miktarını hiç etkilemez","Yalnızca yüzey rengini değiştirir"], a:1, ex:"Yoğun toprak işleme, agregatları parçalayarak korunan organik maddeyi havayla temasa açar ve hızlı oksitlenmesine yol açar; azaltılmış işleme bunu sınırlar.", exEn:"Intensive tillage breaks apart aggregates, exposing protected organic matter to air and causing rapid oxidation; reduced tillage limits this." },
    { id:"q-crop-rotation-om", topic:"practices", q:"Ürün rotasyonu organik madde yönetimine nasıl katkıda bulunur?", qEn:"How does crop rotation contribute to organic matter management?", opts:["Yalnızca pazarlama avantajı sağlar","Farklı kök yapıları ve artık türleri yoluyla organik madde girdisini çeşitlendirir ve zararlı/hastalık döngülerini böler","Organik madde miktarını her zaman azaltır","Yalnızca sulama ihtiyacını artırır"], a:1, ex:"Farklı ürünler farklı miktar ve kalitede kök ve artık bırakır; rotasyon bu çeşitliliği sağlarken aynı zamanda toprak kaynaklı zararlı döngülerini de kesintiye uğratır.", exEn:"Different crops leave different amounts and qualities of roots and residue; rotation provides that diversity while also interrupting soil-borne pest cycles." },
    { id:"q-manure-vs-green-manure", topic:"practices", q:"Hayvan gübresi uygulaması, yeşil gübreden temel olarak nasıl farklıdır?", qEn:"How does manure application fundamentally differ from green manure?", opts:["Aynı şeydir, farklı isimlerle anılır","Hayvan gübresi hayvansal kaynaklıdır ve doğrudan uygulanır; yeşil gübre ise tarlada yetiştirilip toprağa karıştırılan bir bitkidir","Yeşil gübre hiçbir zaman toprağa fayda sağlamaz","Hayvan gübresi yalnızca sentetik bir üründür"], a:1, ex:"İkisi de organik madde ve besin katkısı sağlar, ancak kaynakları ve uygulama yöntemleri farklıdır — biri hayvansal atık, diğeri tarlada yetiştirilen bir bitkidir.", exEn:"Both add organic matter and nutrients, but their source and application differ — one is animal waste, the other a crop grown and incorporated in the field." },
    { id:"q-mulching-contribution", topic:"practices", q:"Malçlamanın organik madde yönetimine katkısı nedir?", qEn:"What is mulching's contribution to organic matter management?", opts:["Hiçbir katkısı yoktur, yalnızca görsel amaçlıdır","Nem kaybını azaltıp sıcaklığı dengelerken, zamanla ayrışarak toprağa organik madde de katar","Organik madde miktarını her zaman azaltır","Yalnızca sulama sistemlerinde kullanılır"], a:1, ex:"Organik malç (saman, talaş gibi) hem toprak yüzeyini korur hem de zamanla ayrışarak ek bir organik madde kaynağı oluşturur.", exEn:"Organic mulch (like straw or wood chips) both protects the soil surface and, decomposing over time, becomes an additional organic matter source." },
    { id:"q-biochar-stability", topic:"practices", q:"Biyokömürü diğer organik madde kaynaklarından ayıran temel özellik nedir?", qEn:"What key property sets biochar apart from other organic matter sources?", opts:["Biyokömür hızla ayrışır ve besin sağlar","Biyokömür, pirolizle üretildiği için toprakta olağanüstü uzun süre (yüzyıllar) kararlı kalabilir","Biyokömür yalnızca sıvı formda bulunur","Biyokömür toprağa hiçbir fayda sağlamaz"], a:1, ex:"Piroliz süreci, biyokömürün kimyasal yapısını mikrobiyal ayrışmaya karşı son derece dirençli hale getirir; bu da onu uzun vadeli karbon depolama için ilgi çekici kılar.", exEn:"The pyrolysis process makes biochar's chemical structure highly resistant to microbial decomposition, which is what makes it attractive for long-term carbon storage." },
    { id:"q-residue-management-cycle", topic:"practices", q:"Bitki artıklarının tarlada bırakılması (uzaklaştırılması yerine) organik madde dengesine nasıl katkıda bulunur?", qEn:"How does leaving crop residues in the field (instead of removing them) contribute to the organic matter balance?", opts:["Hiçbir katkısı yoktur","Artıklar toprağa geri dönerek organik madde girdisinin sürekliliğini sağlar; uzaklaştırma bu döngüyü keser","Artıkları bırakmak organik maddeyi her zaman azaltır","Artık yönetiminin organik maddeyle hiçbir ilişkisi yoktur"], a:1, ex:"Her hasatta artıkların uzaklaştırılması, zamanla toprağa geri dönen organik madde miktarını azaltarak SOM'un düşüşe geçmesine yol açabilir.", exEn:"Removing residues at every harvest reduces the organic matter that would otherwise return to the soil, which can drive SOM into decline over time." },
    { id:"q-vermicomposting-difference", topic:"practices", q:"Solucan kompostunun geleneksel kompostlamadan farkı nedir?", qEn:"How does vermicomposting differ from traditional composting?", opts:["Aynı süreçtir, farklı adı vardır","Ayrışmayı hızlandırmak ve besince zengin bir ürün elde etmek için özel olarak solucanlar kullanılır","Solucan kompostu yalnızca inorganik materyallerle yapılır","Solucan kompostu hiçbir zaman kullanılabilir bir ürün vermez"], a:1, ex:"Solucanlar organik materyali sindirerek hem ayrışmayı hızlandırır hem de besin bakımından zenginleştirilmiş bir döküntü (vermikompost) üretir.", exEn:"Earthworms digesting organic material both speed up decomposition and produce a nutrient-enriched product (vermicompost)." },
    { id:"q-tillage-rotation-synergy", topic:"practices", q:"Azaltılmış toprak işleme ile ürün rotasyonunun birlikte kullanılması neden organik madde yönetiminde özellikle etkili olabilir?", qEn:"Why can combining reduced tillage with crop rotation be especially effective for organic matter management?", opts:["İkisi birbiriyle çelişir, birlikte kullanılamaz","Biri fiziksel korumayı (azaltılmış işleme), diğeri girdi çeşitliliğini (rotasyon) sağlayarak birbirini tamamlar","Yalnızca biri etkilidir, diğerinin hiçbir katkısı yoktur","İkisi de yalnızca sulama miktarını etkiler"], a:1, ex:"Azaltılmış işleme organik maddenin fiziksel olarak korunmasına yardımcı olurken, rotasyon farklı kök sistemleri ve artık türleriyle girdi çeşitliliği sağlar — birlikte daha güçlü bir etki yaratırlar.", exEn:"Reduced tillage helps physically protect organic matter, while rotation provides input diversity through different root systems and residue types — together they create a stronger effect." },
    { id:"q-biochar-vs-fresh-residue", topic:"practices", q:"Biyokömür ile taze bitki artığı, toprağa eklendiğinde karbon kalıcılığı açısından nasıl farklılaşır?", qEn:"How do biochar and fresh plant residue differ in carbon persistence when added to soil?", opts:["İkisi de aynı hızda ayrışır","Taze artık aylar-yıllar içinde büyük ölçüde ayrışırken, biyokömür yüzyıllar boyunca kararlı kalabilir","Biyokömür taze artıktan daha hızlı ayrışır","İkisinin de karbon kalıcılığı yoktur"], a:1, ex:"Biyokömürün piroliz sırasında oluşan kimyasal yapısı, onu mikrobiyal ayrışmaya karşı taze bitki artığından çok daha dirençli hale getirir.", exEn:"The chemical structure biochar develops during pyrolysis makes it far more resistant to microbial decomposition than fresh plant residue." },
    { id:"q-mulch-vs-cover-crop", topic:"practices", q:"Malç ile örtü bitkisi arasındaki fark nedir?", qEn:"What is the difference between mulch and a cover crop?", opts:["Aynı şeydir","Malç genellikle tarla dışından getirilen veya kesilmiş bir materyaldir; örtü bitkisi ise doğrudan tarlada canlı olarak yetiştirilir","Malç her zaman canlı bir bitkidir","Örtü bitkisi hiçbir zaman toprağı örtmez"], a:1, ex:"Malç pasif bir örtüdür (genellikle kesilmiş/getirilmiş materyal), örtü bitkisi ise aktif olarak büyüyen, kök salan canlı bir bitkidir — ikisi farklı mekanizmalarla fayda sağlar.", exEn:"Mulch is a passive cover (usually cut/brought-in material), while a cover crop is a living, actively growing, rooting plant — they benefit the soil through different mechanisms." },
    { id:"q-manure-nutrient-om-balance", topic:"practices", q:"Hayvan gübresi uygulamasında hem besin hem organik madde faydasını dengelemek neden önemlidir?", qEn:"Why is it important to balance both nutrient and organic matter benefits when applying manure?", opts:["Önemli değildir, yalnızca besin miktarına bakılır","Aşırı gübre uygulaması, organik madde faydası sağlarken besin fazlalığına (örn. fosfor birikimi) yol açabilir","Hayvan gübresi hiçbir zaman fazla uygulanamaz","Organik madde faydası besin faydasından önemsizdir"], a:1, ex:"Gübre hem N hem P içerir; N ihtiyacına göre hesaplanan bir uygulama miktarı, zamanla P'nin toprakta aşırı birikmesine yol açabilir — bu yüzden dengeli planlama gerekir.", exEn:"Manure contains both N and P; an application rate calculated for N needs can lead to P over-accumulating in the soil over time — which is why balanced planning matters." },
    { id:"q-residue-removal-tradeoff", topic:"practices", q:"Bitki artıklarının biyoenerji için uzaklaştırılması hangi ödünleşimi (trade-off) içerir?", qEn:"What trade-off does removing crop residues for bioenergy involve?", opts:["Hiçbir ödünleşim yoktur, yalnızca fayda vardır","Enerji/gelir faydası sağlarken, toprağa dönen organik madde miktarını azaltarak uzun vadeli toprak sağlığını riske atabilir","Artık uzaklaştırma toprak organik maddesini her zaman artırır","Bu ödünleşim yalnızca teoriktir, pratikte önemsizdir"], a:1, ex:"Artıkların biyoyakıt için toplanması kısa vadeli ekonomik fayda sağlayabilir, ama toprağa dönen organik madde miktarını azaltarak uzun vadede verimlilik ve strüktürü etkileyebilir.", exEn:"Collecting residues for biofuel can provide short-term economic benefit, but by reducing the organic matter returned to soil, it can affect long-term fertility and structure." },
    { id:"q-vermicompost-quality", topic:"practices", q:"Vermikompostun (solucan kompostu) bitkiler için özellikle değerli kabul edilmesinin bir nedeni nedir?", qEn:"What is one reason vermicompost is considered especially valuable for plants?", opts:["Hiçbir besin içermez","Solucan sindirim sürecinden geçtiği için besin elementleri genellikle daha kolay yarayışlı formda bulunur","Yalnızca dekoratif amaçlıdır","Solucan kompostu toprağı her zaman asitleştirir"], a:1, ex:"Solucanların sindirim süreci, organik materyaldeki besin elementlerinin bir kısmını bitkiler için daha kolay alınabilir formlara dönüştürebilir.", exEn:"The earthworm digestion process can convert some of the nutrients in organic material into forms more readily available to plants." },

    // --- structure-carbon (15) ---
    { id:"q-aggregate-stability-practice", topic:"structure-carbon", q:"Hangi uygulama toprak agregat stabilitesini en doğrudan artırır?", qEn:"Which practice most directly increases soil aggregate stability?", opts:["Tüm bitki artıklarını uzaklaştırmak","Toprak organik madde içeriğini artırmak","Aşırı, tekrarlanan toprak işleme","Yalnızca inorganik tuz uygulamak"], a:1, ex:"Organik madde — özellikle mikrobiyal yan ürünler ve kök salgıları — mineral parçacıkları erozyona dirençli, kararlı agregatlar halinde bir araya getirir.", exEn:"Organic matter — especially microbial byproducts and root exudates — binds mineral particles into stable aggregates that resist erosion." },
    { id:"q-som-carbon-seq", topic:"structure-carbon", q:"Toprak organik maddesi karbon tutulumuna nasıl katkıda bulunur?", qEn:"How does soil organic matter contribute to carbon sequestration?", opts:["Depolanan karbonu hızla serbest bırakarak","Karbonu nispeten kararlı formlarda depolayarak atmosfere geri dönen miktarı azaltarak","Atmosferik karbonla hiçbir ilişkisi yoktur","Yalnızca azot döngüsünü etkiler"], a:1, ex:"Kararlı hale gelmiş toprak organik maddesi (humus), karbonu on yıllarca hatta yüzyıllarca tutabilir; bu da onu bir kaynak değil bir yutak (sink) yapar.", exEn:"Stabilized SOM (humus) can hold carbon for decades to centuries, acting as a sink rather than a source." },
    { id:"q-glomalin-aggregate-role", topic:"structure-carbon", q:"Glomalin nedir ve agregat stabilitesine nasıl katkıda bulunur?", qEn:"What is glomalin, and how does it contribute to aggregate stability?", opts:["Bir toprak minerali türüdür","Mikorizal mantarlar tarafından üretilen, toprak parçacıklarını bir arada tutan yapışkan bir glikoproteindir","Yalnızca bakteriler tarafından üretilen bir toksindir","Agregat stabilitesiyle hiçbir ilgisi yoktur"], a:1, ex:"Glomalin, mikorizal hiflerin ürettiği yapışkan bir madde olarak, mineral parçacıkları birbirine yapıştırarak kararlı agregatların oluşumuna doğrudan katkıda bulunur.", exEn:"As a sticky substance produced by mycorrhizal hyphae, glomalin directly glues mineral particles together, contributing to the formation of stable aggregates." },
    { id:"q-macro-vs-micro-aggregate", topic:"structure-carbon", q:"Makroagregatlar ile mikroagregatlar arasındaki temel fark nedir?", qEn:"What is the key difference between macroaggregates and microaggregates?", opts:["Aynı boyuttadırlar","Makroagregatlar daha büyüktür ve kök/hif ağlarınca bir arada tutulur; mikroagregatlar bunların içinde, kimyasal bağlarla oluşan daha küçük birimlerdir","Mikroagregatlar her zaman makroagregatlardan daha büyüktür","İkisi arasında hiçbir yapısal ilişki yoktur"], a:1, ex:"Makroagregatlar (>250 μm) kök ve hiflerle fiziksel olarak bir arada tutulurken, bunların içindeki mikroagregatlar daha kalıcı kimyasal bağlarla oluşur.", exEn:"Macroaggregates (>250 μm) are held together physically by roots and hyphae, while the microaggregates within them form through more persistent chemical bonds." },
    { id:"q-carbon-saturation-def", topic:"structure-carbon", q:"Karbon doygunluğu kavramı neyi ifade eder?", qEn:"What does the concept of carbon saturation refer to?", opts:["Toprağın sınırsız karbon depolayabileceğini","Bir toprağın, kil ve silt parçacıklarıyla fiziksel olarak koruyabileceği organik karbon miktarının bir üst sınırı olduğunu","Karbonun toprakta hiçbir zaman depolanamadığını","Yalnızca kumlu toprakların karbon depolayabildiğini"], a:1, ex:"Bir toprak bu doygunluk sınırına yaklaştıkça, ek organik madde girdisinin karbon stoklarını artırma etkisi azalır.", exEn:"As a soil approaches this saturation limit, additional organic matter input has a diminishing effect on increasing carbon stocks." },
    { id:"q-om-bulk-density-effect", topic:"structure-carbon", q:"Organik madde artışı, toprağın hacim ağırlığını nasıl etkiler?", qEn:"How does an increase in organic matter affect a soil's bulk density?", opts:["Hacim ağırlığını artırır, toprağı sıkıştırır","Gözenekliliği artırarak hacim ağırlığını düşürür, kök nüfuzunu kolaylaştırır","Hiçbir etkisi yoktur","Yalnızca toprağın rengini değiştirir"], a:1, ex:"Organik madde, mineral parçacıklara göre daha az yoğun olduğundan ve gözenek oluşumunu teşvik ettiğinden, artışı genellikle hacim ağırlığının düşmesine yol açar.", exEn:"Because organic matter is less dense than mineral particles and promotes pore formation, an increase generally leads to lower bulk density." },
    { id:"q-om-infiltration-effect", topic:"structure-carbon", q:"Organik madde, su sızma hızını nasıl etkiler?", qEn:"How does organic matter affect water infiltration rate?", opts:["Su sızmasını tamamen engeller","Kararlı agregatlar oluşturarak su geçirgen gözenekler yaratır, böylece yüzey akışını azaltıp sızmayı artırır","Sızma hızıyla hiçbir ilgisi yoktur","Yalnızca çok kurak iklimlerde etkilidir"], a:1, ex:"İyi agregatlaşmış, organik maddece zengin bir toprak, suyun yüzeyde birikip akması yerine profil içine daha kolay sızmasını sağlar.", exEn:"A well-aggregated, organic-matter-rich soil lets water infiltrate into the profile more easily instead of pooling and running off the surface." },
    { id:"q-om-erosion-resistance-mechanism", topic:"structure-carbon", q:"Organik madde, erozyona karşı direnci nasıl artırır?", qEn:"How does organic matter increase resistance to erosion?", opts:["Toprak parçacıklarını birbirinden ayırarak","Kararlı agregatlar oluşturarak tekil parçacıkların rüzgar veya suyla kolayca taşınmasını zorlaştırarak","Erozyon direnciyle hiçbir ilgisi yoktur","Yalnızca yüzeyde ince bir tabaka oluşturarak"], a:1, ex:"Agregatlaşmış toprak parçacıkları, tekil ince parçacıklara göre rüzgar veya su tarafından çok daha zor taşınır; bu doğrudan erozyonu azaltır.", exEn:"Aggregated soil particles are far harder for wind or water to carry away than individual fine particles, directly reducing erosion." },
    { id:"q-active-stable-carbon-diff", topic:"structure-carbon", q:"Aktif karbon havuzu ile kararlı (pasif) karbon havuzu arasındaki fark nedir?", qEn:"What is the difference between the active carbon pool and the stable (passive) carbon pool?", opts:["Aynı hızda döngüye girerler","Aktif havuz hızla döngüye giren, kısa ömürlü karbonu; kararlı havuz ise onlarca-yüzlerce yıl kalabilen karbonu temsil eder","Kararlı havuz her zaman aktif havuzdan küçüktür","Aktif havuz asla ayrışmaz"], a:1, ex:"Bu iki havuzu ayırt etmek, bir toprak yönetim uygulamasının kısa vadeli mi yoksa uzun vadeli karbon etkisi mi yarattığını anlamaya yardımcı olur.", exEn:"Distinguishing these two pools helps clarify whether a soil management practice is having a short-term or a long-term carbon effect." },
    { id:"q-carbon-turnover-time-def", topic:"structure-carbon", q:"Karbon havuzlarının 'döngü süresi' kavramı neyi ifade eder?", qEn:"What does the concept of carbon pool 'turnover time' refer to?", opts:["Toprağın kaç yıl işlendiğini","Farklı organik madde fraksiyonlarının topraktan tamamen kaybolmadan önce ne kadar süre kaldığını","Yalnızca hasat döngüsünü","Toprağın jeolojik yaşını"], a:1, ex:"Labil fraksiyonlar aylar içinde döngüye girerken, kararlı fraksiyonlar yüzyıllar boyunca toprakta kalabilir — bu geniş zaman ölçeği farkı yönetim kararlarını etkiler.", exEn:"Labile fractions cycle within months while stable fractions can remain in soil for centuries — this wide difference in timescale shapes management decisions." },
    { id:"q-climate-solution-reasoning", topic:"structure-carbon", q:"Toprakta karbon tutulumu, iklim değişikliğiyle mücadelede neden 'doğal bir çözüm' olarak değerlendirilir?", qEn:"Why is soil carbon sequestration considered a 'natural climate solution'?", opts:["Toprağın iklimle hiçbir ilgisi yoktur","Atmosferdeki CO₂'yi toprak organik maddesi biçiminde depolayarak atmosferik konsantrasyonun azaltılmasına katkıda bulunabilir","Toprak karbonu her zaman atmosfere geri döner, hiçbir faydası yoktur","Yalnızca ormanlar karbon tutabilir, topraklar tutamaz"], a:1, ex:"Tarım topraklarında organik madde biriktirme uygulamaları (azaltılmış işleme, örtü bitkileri), atmosferik CO₂'yi toprakta depolayarak iklim değişikliğini hafifletmeye katkıda bulunan bir strateji olarak görülür.", exEn:"Practices that build organic matter in farmland (reduced tillage, cover crops) are seen as a strategy that helps mitigate climate change by storing atmospheric CO2 in the soil." },
    { id:"q-glomalin-mycorrhiza-link", topic:"structure-carbon", q:"Glomalin üretimi hangi biyolojik ilişkiyle doğrudan bağlantılıdır?", qEn:"Glomalin production is directly linked to which biological relationship?", opts:["Bitki-böcek etkileşimiyle","Mikorizal mantar-bitki kökü simbiyozuyla","Yalnızca bakteriyel azot fiksasyonuyla","Hiçbir biyolojik ilişkiyle bağlantılı değildir"], a:1, ex:"Glomalin, kök sistemleriyle simbiyotik ilişki kuran mikorizal mantarların hifleri tarafından üretilir; bu da toprak biyolojisi ile fiziksel yapı arasındaki doğrudan bağlantıyı gösterir.", exEn:"Glomalin is produced by the hyphae of mycorrhizal fungi that form a symbiotic relationship with root systems — a direct link between soil biology and physical structure." },
    { id:"q-carbon-saturation-management", topic:"structure-carbon", q:"Bir toprak karbon doygunluğuna yaklaştığında, üreticiler için pratik çıkarım nedir?", qEn:"What is the practical takeaway for growers when a soil is approaching carbon saturation?", opts:["Organik madde eklemeyi tamamen bırakmalıdırlar","Ek organik madde girdisinin karbon stoku artırma etkisi azalabilir, ancak toprak sağlığı için diğer faydaları (besin, strüktür) sürebilir","Toprak artık hiçbir organik madde alamaz","Karbon doygunluğu geri döndürülemez bir durumdur"], a:1, ex:"Doygunluğa yaklaşan bir toprakta ek girdilerin net karbon depolama etkisi azalabilir, ama organik madde döngüsünün diğer faydaları (besin sağlama, agregatlaşma) devam eder.", exEn:"As a soil nears saturation, additional inputs' net carbon-storage effect may shrink, but the organic matter cycle's other benefits (nutrient supply, aggregation) continue." },
    { id:"q-aggregate-infiltration-link", topic:"structure-carbon", q:"Agregat stabilitesi ile su sızma hızı arasındaki ilişki nedir?", qEn:"What is the relationship between aggregate stability and water infiltration rate?", opts:["Hiçbir ilişkileri yoktur","Kararlı agregatlar, gözenek yapısını koruyarak suyun toprağa daha kolay sızmasını sağlar; agregatlar dağılırsa gözenekler tıkanabilir","Agregat stabilitesi yalnızca erozyonu etkiler, sızmayı etkilemez","Daha az kararlı agregatlar her zaman daha hızlı sızma sağlar"], a:1, ex:"Kararsız agregatlar suyla temas ettiğinde dağılabilir ve yüzeyde ince parçacıklardan oluşan bir tabaka (kaymak tabakası) oluşturarak sızmayı engelleyebilir; kararlı agregatlar bunu önler.", exEn:"Unstable aggregates can break apart on contact with water and form a surface crust of fine particles that blocks infiltration; stable aggregates prevent this." },
    { id:"q-stable-carbon-turnover-patience", topic:"structure-carbon", q:"Kararlı karbon havuzunun yüzyıllar süren döngü süresi, toprak karbon yönetimi kararlarını nasıl etkilemelidir?", qEn:"How should the centuries-long turnover time of the stable carbon pool influence soil carbon management decisions?", opts:["Hiçbir etkisi olmamalıdır, kararlar yalnızca bu yıla göre verilmelidir","Karbon biriktirme stratejilerinin etkisinin yıllar hatta on yıllar sürebileceğinin, bu yüzden sabır ve süreklilik gerektirdiğinin kabul edilmesi gerekir","Kararlı karbon anında oluşur, hemen sonuç beklenmelidir","Yönetim kararları yalnızca aktif havuzu hedeflemelidir"], a:1, ex:"Kararlı karbon havuzunun oluşumu yavaş bir süreç olduğundan, toprak karbon biriktirme stratejilerinin sonuçları genellikle yıllar sonra belirgin hale gelir — bu, sürekli ve uzun vadeli bir yaklaşım gerektirir.", exEn:"Because building the stable carbon pool is a slow process, the results of soil carbon-building strategies typically become visible only years later — requiring a consistent, long-term approach." }
  ]
};
